  printfIntResult: {{ printf "number: %d" $testData | quote }}
  {{- end }}
  # Test: printf %f - expects float
  {{- if .Values.testPrintfFloat }}
  printfFloatResult: {{ printf "float: %f" $testData | quote }}
  {{- end }}
  # Test: printf %t - expects boolean
  {{- if .Values.testPrintfBool }}
